import sys

class Solution:
    def toPostfix(self, expr: str) -> str:
        sys.setrecursionlimit(100000)
        prec = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
        i = 0
        def atom(out):
            nonlocal i
            if expr[i] == "(":
                i += 1
                parse(1, out)
                i += 1
            else:
                out.append(expr[i])
                i += 1
        def parse(min_prec, out):
            nonlocal i
            atom(out)
            while i < len(expr) and expr[i] in prec and prec[expr[i]] >= min_prec:
                op = expr[i]
                i += 1
                parse(prec[op] if op == "^" else prec[op] + 1, out)
                out.append(op)
        out = []
        parse(1, out)
        return "".join(out)

