class Solution {
    private String e;
    private int i;
    private StringBuilder out;

    private int prec(char c) {
        return c == '+' || c == '-' ? 1 : c == '*' || c == '/' ? 2 : c == '^' ? 3 : 0;
    }

    public String toPostfix(String expr) {
        e = expr;
        i = 0;
        out = new StringBuilder();
        parse(1);
        return out.toString();
    }

    private void atom() {
        if (e.charAt(i) == '(') { i++; parse(1); i++; }
        else out.append(e.charAt(i++));
    }

    private void parse(int minPrec) {
        atom();
        while (i < e.length() && prec(e.charAt(i)) >= minPrec && prec(e.charAt(i)) > 0) {
            char op = e.charAt(i++);
            parse(op == '^' ? prec(op) : prec(op) + 1);
            out.append(op);
        }
    }
}

