class Solution {
    private int prec(char c) {
        return c == '+' || c == '-' ? 1 : c == '*' || c == '/' ? 2 : c == '^' ? 3 : 0;
    }

    public String toPostfix(String expr) {
        StringBuilder out = new StringBuilder();
        char[] ops = new char[expr.length()];
        int top = 0;
        for (char c : expr.toCharArray()) {
            if (c == '(') ops[top++] = c;
            else if (c == ')') {
                while (ops[top - 1] != '(') out.append(ops[--top]);
                top--;
            } else if (prec(c) > 0) {
                while (top > 0 && ops[top - 1] != '(' && (prec(ops[top - 1]) > prec(c) || (prec(ops[top - 1]) == prec(c) && c != '^'))) out.append(ops[--top]);
                ops[top++] = c;
            } else out.append(c);
        }
        while (top > 0) out.append(ops[--top]);
        return out.toString();
    }
}

